class Solution {
    public int[] countRectangles(int[][] rectangles, int[][] points) {
        List<List<Integer>> buckets = new ArrayList<>();
        for (int i = 0; i <= 100; i++) buckets.add(new ArrayList<>());
        for (int[] r : rectangles) buckets.get(r[1]).add(r[0]);
        for (List<Integer> b : buckets) Collections.sort(b);
        int[] res = new int[points.length];
        for (int j = 0; j < points.length; j++) {
            int c = 0;
            for (int h = points[j][1]; h <= 100; h++) {
                List<Integer> b = buckets.get(h);
                int idx = Collections.binarySearch(b, points[j][0]);
                if (idx < 0) idx = -(idx + 1);
                c += b.size() - idx;
            }
            res[j] = c;
        }
        return res;
    }
}

