var countRectangles = function(rectangles, points) {
    const buckets = Array.from({length: 101}, () => []);
    for (const [l, h] of rectangles) buckets[h].push(l);
    for (const b of buckets) b.sort((a,b)=>a-b);
    const lb = (b, x) => { let lo=0, hi=b.length; while(lo<hi){const m=(lo+hi)>>1; if(b[m]<x)lo=m+1;else hi=m;} return lo; };
    return points.map(([x, y]) => {
        let c = 0;
        for (let h = y; h <= 100; h++) c += buckets[h].length - lb(buckets[h], x);
        return c;
    });
};

