class Solution:
    def countRectangles(self, rectangles: List[List[int]], points: List[List[int]]) -> List[int]:
        ws = sorted(set(l for l, h in rectangles))
        idx = {w: i + 1 for i, w in enumerate(ws)}
        bit = [0] * (len(ws) + 1)
        def upd(i):
            while i < len(bit):
                bit[i] += 1; i += i & (-i)
        def qry(i):
            s = 0
            while i > 0:
                s += bit[i]; i -= i & (-i)
            return s
        rects = sorted(rectangles, key=lambda r: -r[1])
        pts = sorted(range(len(points)), key=lambda j: -points[j][1])
        res = [0] * len(points)
        p = 0
        for j in pts:
            x, y = points[j]
            while p < len(rects) and rects[p][1] >= y:
                upd(idx[rects[p][0]]); p += 1
            lo = bisect.bisect_left(ws, x) + 1
            res[j] = p - qry(lo - 1)
        return res
