class Solution {
public:
    vector<int> bit;
    void upd(int i) { for (; i < bit.size(); i += i & (-i)) bit[i]++; }
    int qry(int i) { int s = 0; for (; i > 0; i -= i & (-i)) s += bit[i]; return s; }
    vector<int> countRectangles(vector<vector<int>>& rectangles, vector<vector<int>>& points) {
        vector<int> ws;
        for (auto& r : rectangles) ws.push_back(r[0]);
        sort(ws.begin(), ws.end()); ws.erase(unique(ws.begin(), ws.end()), ws.end());
        bit.assign(ws.size() + 1, 0);
        vector<int> ord(points.size());
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int a, int b){ return points[a][1] > points[b][1]; });
        sort(rectangles.begin(), rectangles.end(), [](auto& a, auto& b){ return a[1] > b[1]; });
        vector<int> res(points.size());
        int p = 0;
        for (int j : ord) {
            int x = points[j][0], y = points[j][1];
            while (p < rectangles.size() && rectangles[p][1] >= y) {
                int i = lower_bound(ws.begin(), ws.end(), rectangles[p][0]) - ws.begin() + 1;
                upd(i); p++;
            }
            int lo = lower_bound(ws.begin(), ws.end(), x) - ws.begin() + 1;
            res[j] = p - qry(lo - 1);
        }
        return res;
    }
};

