    void upd(int i) { for (; i < bit.length; i += i & (-i)) bit[i]++; }
    int qry(int i) { int s = 0; for (; i > 0; i -= i & (-i)) s += bit[i]; return s; }
    public int[] countRectangles(int[][] rectangles, int[][] points) {
        TreeSet<Integer> set = new TreeSet<>();
        for (int[] r : rectangles) set.add(r[0]);
        List<Integer> ws = new ArrayList<>(set);
        bit = new int[ws.size() + 1];
        Integer[] ord = new Integer[points.length];
        for (int i = 0; i < ord.length; i++) ord[i] = i;
        Arrays.sort(ord, (a, b) -> points[b][1] - points[a][1]);
        Arrays.sort(rectangles, (a, b) -> b[1] - a[1]);
        int[] res = new int[points.length];
        int p = 0;
        for (int j : ord) {
            int x = points[j][0], y = points[j][1];
            while (p < rectangles.length && rectangles[p][1] >= y) {
                int i = Collections.binarySearch(ws, rectangles[p][0]);
                upd(i + 1); p++;
            }
            int lo = Collections.binarySearch(ws, x);
            if (lo < 0) lo = -(lo + 1);
            res[j] = p - qry(lo);
        }
        return res;
    }
}

