var countRectangles = function(rectangles, points) {
    const ws = [...new Set(rectangles.map(r => r[0]))].sort((a,b)=>a-b);
    const bit = new Array(ws.length + 1).fill(0);
    const upd = i => { for (; i < bit.length; i += i & (-i)) bit[i]++; };
    const qry = i => { let s = 0; for (; i > 0; i -= i & (-i)) s += bit[i]; return s; };
    const ord = points.map((_, i) => i).sort((a,b) => points[b][1] - points[a][1]);
    rectangles.sort((a,b) => b[1] - a[1]);
    const res = new Array(points.length);
    let p = 0;
    for (const j of ord) {
        const [x, y] = points[j];
        while (p < rectangles.length && rectangles[p][1] >= y) {
            upd(ws.indexOf(rectangles[p][0]) + 1); p++;
        }
        let lo = 0, hi = ws.length;
        while (lo < hi) { const m = (lo+hi)>>1; if (ws[m] < x) lo = m+1; else hi = m; }
        res[j] = p - qry(lo);
    }
    return res;
};
